    "assemble.ui.0380": "硬件模型",
    "assemble.ui.0381": "Arduino UNO Q 的板卡模型由 Arduino 官方 STEP 文件转换而来，",
    "assemble.ui.0382": "原始文件",
    "assemble.ui.0383": "识别图使用本批 HD1910 舵机的本地实物照片；照片和模型均不随开源代码分发。其余舵机、扩展板、舵盘、线缆和螺丝为参考照片手工建模的示意几何；孔位配合、电气针序和扭矩尚未实物验证。",
    "assemble.ui.0384": "音乐感受因人而异；本页曲目不作医疗或疗效承诺。"
