    "assemble.ui.0372": "편곡 및 연주 : Kevin MacLeod",
    "assemble.ui.0373": "저자 웹사이트에서 제공되는 녹음을 사용하고, 다시 인코딩하고, 음량을 통일하고, 시작과 끝 부분에 페이드를 추가했습니다. ISRC: USUAN1100787.",
