    "assemble.ui.0375": "작곡: 볼프강 아마데우스 모차르트",
    "assemble.ui.0376": "버전: Mutopia Public Domain MIDI를 기반으로 한 디지털 피아노 렌더링; Ryo XP가 업로드한 Wikimedia Commons.",
    "assemble.ui.0377": "원본 오디오 및 설명",
    "assemble.ui.0378": "녹음되고 통일된 음량과 시작과 끝 부분에 페이드가 추가되었습니다. 이 버전은 디지털 방식으로 수행됩니다.",
    "assemble.ui.0379": "외부 샘플을 사용하지 않고 이 프로토타입을 위해 로컬에서 합성된 부드러운 이중 톤입니다.",
    "assemble.ui.0380": "하드웨어 모델",
    "assemble.ui.0381": "Arduino UNO Q의 보드 모델은 공식 Arduino STEP 파일에서 변환되었습니다.",
    "assemble.ui.0382": "원본파일",
    "assemble.ui.0383": "식별 다이어그램은 이 HD1910 서보 배치의 로컬 실제 사진을 사용합니다. 사진이나 모델 모두 오픈 소스 코드와 함께 배포되지 않습니다. 나머지 서보, 확장 보드, 서보 혼, 케이블 및 나사는 참조 사진을 기반으로 수동으로 모델링한 도식적 형상입니다. 구멍 위치, 전기 핀 순서 및 토크는 아직 물리적으로 검증되지 않았습니다.",
    "assemble.ui.0384": "음악 경험은 사람마다 다릅니다. 이 페이지의 트랙은 어떠한 의학적 또는 치료적 약속도 하지 않습니다."
