    "assemble.ui.0350": "Instructions pédagogiques : Les positions des trous, la coordination des connexions, les révisions de la carte et les extrémités des lignes n'ont pas encore été vérifiées physiquement.",
    "assemble.ui.0351": "Comparaison de photos originales",
    "assemble.ui.0352": "Fermer le film original",
    "assemble.ui.0353": "Extrait de la vidéo que vous avez fournie · 20h58—23h10",
    "assemble.ui.0354": "Préparation et numérotation des servos",
    "assemble.ui.0355": "Vis d'origine",
    "assemble.ui.0356": "Marge de fin de ligne",
