    "assemble.ui.0370": "Prototipo v3.7 ensamblado independientemente · Se utiliza para crear una atmósfera de visualización suave.",
    "assemble.ui.0371": "Compositor: Erik Satie",
    "assemble.ui.0372": "Arreglo e interpretación: Kevin MacLeod",
    "assemble.ui.0373": "Grabaciones usadas proporcionadas en el sitio web del autor, recodificadas, sonoridad unificada y fundidos agregados al principio y al final. ISRC: USUAN1100787.",
    "assemble.ui.0374": "Mozart Sonata para piano K.545 Segundo movimiento, Andante",
    "assemble.ui.0375": "Compositor: Wolfgang Amadeus Mozart",
    "assemble.ui.0376": "Versión: Representación de piano digital basada en MIDI de dominio público de Mutopia; Wikimedia Commons subido por Ryo xp.",
    "assemble.ui.0377": "Audio original y descripción",
    "assemble.ui.0378": "Volumen recodificado y unificado y fundidos añadidos al principio y al final. Esta versión se realiza en formato digital.",
    "assemble.ui.0379": "Un doble tono suave sintetizado localmente para este prototipo, sin el uso de muestras externas.",
    "assemble.ui.0380": "Modelo de hardware",
    "assemble.ui.0381": "El modelo de placa de Arduino UNO Q se convierte desde el archivo oficial Arduino STEP.",
    "assemble.ui.0382": "Archivo original",
    "assemble.ui.0383": "El diagrama de identificación utiliza fotografías físicas locales de este lote de servos HD1910; Ni fotos ni modelos se distribuyen con código fuente abierto. El resto de servos, placas de expansión, brazos del servo, cables y tornillos son geometrías esquemáticas modeladas manualmente en base a las fotos de referencia; el posicionamiento del orificio, la secuencia de los pasadores eléctricos y el torque aún no se han verificado físicamente.",
    "assemble.ui.0384": "La experiencia musical varía de persona a persona; Las pistas de esta página no hacen ninguna promesa médica o terapéutica."
