    "assemble.ui.0377": "Áudio e descrição originais",
    "assemble.ui.0378": "Volume recodificado e unificado e fades adicionados no início e no final. Esta versão é realizada digitalmente.",
    "assemble.ui.0379": "Um tom duplo suave sintetizado localmente para este protótipo, sem o uso de samples externos.",
    "assemble.ui.0380": "Modelo de hardware",
    "assemble.ui.0381": "O modelo da placa do Arduino UNO Q é convertido do arquivo STEP oficial do Arduino.",
    "assemble.ui.0382": "Arquivo original",
    "assemble.ui.0383": "O diagrama de identificação utiliza fotos físicas locais deste lote de servos HD1910; nem fotos nem modelos são distribuídos com código-fonte aberto. O restante dos servos, placas de expansão, braços do servo, cabos e parafusos são geometrias esquemáticas modeladas manualmente com base nas fotos de referência; o posicionamento do furo, a sequência elétrica dos pinos e o torque ainda não foram verificados fisicamente.",
    "assemble.ui.0384": "A experiência musical varia de pessoa para pessoa; as faixas desta página não fazem nenhuma promessa médica ou terapêutica."
