    "assemble.ui.0369": "Источник фортепианной музыки",
    "assemble.ui.0370": "Самостоятельно собранный прототип v3.7 · Используется для создания мягкой атмосферы просмотра.",
    "assemble.ui.0371": "Композитор: Эрик Сати",
    "assemble.ui.0372": "Аранжировка и исполнение: Кевин МакЛауд",
    "assemble.ui.0373": "Использованы записи, предоставленные на сайте автора, перекодированы, унифицированы громкость и добавлены затухания в начале и конце. ISRC: USUAN1100787.",
    "assemble.ui.0374": "Моцарт Соната для фортепиано K.545 Вторая часть, Анданте",
    "assemble.ui.0375": "Композитор: Вольфганг Амадей Моцарт.",
    "assemble.ui.0376": "Версия: рендеринг цифрового фортепиано на основе Mutopia Public Domain MIDI; Викисклад, загруженный Ryo xp.",
    "assemble.ui.0377": "Оригинальный звук и описание.",
    "assemble.ui.0378": "Перекодирована, унифицирована громкость и добавлены затухания в начале и конце. Эта версия выполнена в цифровом формате.",
    "assemble.ui.0379": "Мягкий двойной тон, синтезированный локально для этого прототипа, без использования внешних сэмплов.",
    "assemble.ui.0380": "Модель оборудования",
    "assemble.ui.0381": "Модель платы Arduino UNO Q конвертирована из официального файла Arduino STEP.",
    "assemble.ui.0382": "Исходный файл",
    "assemble.ui.0383": "Идентификационная диаграмма использует местные физические фотографии этой партии сервоприводов HD1910; ни фотографии, ни модели не распространяются с открытым исходным кодом. Остальные сервоприводы, платы расширения, качалки сервоприводов, кабели и винты представляют собой схематическую геометрию, смоделированную вручную на основе эталонных фотографий; расположение отверстий, последовательность электрических контактов и крутящий момент еще не были физически проверены.",
    "assemble.ui.0384": "Музыкальный опыт варьируется от человека к человеку; треки на этой странице не несут никакой медицинской или терапевтической пользы."
