    "assemble.ui.0371": "الحان: إريك ساتي",
    "assemble.ui.0372": "توزيع وأداء: كيفن ماكلويد",
    "assemble.ui.0373": "التسجيلات المستعملة المتوفرة في موقع المؤلف، أعيد تشفيرها وتوحيد جهارة الصوت وإضافة التلاشي في البداية والنهاية. ISRC: USUAN1100787.",
    "assemble.ui.0374": "سوناتا بيانو موزارت K.545 الحركة الثانية، أندانتي",
